#!/usr/bin/env python3

"""Generate deterministic, public credentials for the NATS authentication tests.

Install e2e_test/source_inline/requirements.txt before running this script.
"""

import argparse
import base64
import hashlib
import json
from pathlib import Path

import nkeys


ISSUED_AT = 1790467200  # 2026-09-27 UTC
GENERATED_HEADER = (
    "# Generated by generate_auth.py; public test credentials only.\n"
)
SERVER_CONFIG = (
    GENERATED_HEADER
    + "port: 4222\n"
    + "http_port: 8222\n"
    + "jetstream { store_dir: /tmp/nats-auth }\n"
)


def make_key(label: str, prefix: int):
    seed = hashlib.sha256(f"risingwave-nats-auth-test:{label}".encode()).digest()
    return nkeys.from_seed(nkeys.encode_seed(seed, prefix))


def json_bytes(value: dict) -> bytes:
    return json.dumps(value, separators=(",", ":")).encode()


def base64url(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode()


def make_jwt(issuer, subject, kind: str, **nats_claims) -> str:
    claims = {
        "iat": ISSUED_AT,
        "iss": issuer.public_key.decode(),
        "sub": subject.public_key.decode(),
        "nats": {"type": kind, "version": 2, **nats_claims},
    }
    # NATS claim IDs are unpadded base32 SHA-256 hashes of the claims without jti.
    claims["jti"] = (
        base64.b32encode(hashlib.sha256(json_bytes(claims)).digest())
        .rstrip(b"=")
        .decode()
    )
    header = {"typ": "JWT", "alg": "ed25519-nkey"}
    payload = f"{base64url(json_bytes(header))}.{base64url(json_bytes(claims))}"
    return f"{payload}.{base64url(issuer.sign(payload.encode()))}"


def generate_auth(output_dir: Path) -> None:
    operator = make_key("operator", nkeys.PREFIX_BYTE_OPERATOR)
    system = make_key("system", nkeys.PREFIX_BYTE_ACCOUNT)
    account = make_key("account", nkeys.PREFIX_BYTE_ACCOUNT)
    user = make_key("user", nkeys.PREFIX_BYTE_USER)
    wrong_user = make_key("wrong-user", nkeys.PREFIX_BYTE_USER)

    operator_jwt = make_jwt(
        operator, operator, "operator", system_account=system.public_key.decode()
    )
    system_jwt = make_jwt(operator, system, "account")
    account_jwt = make_jwt(
        operator,
        account,
        "account",
        limits={
            "subs": -1,
            "data": -1,
            "payload": -1,
            "imports": -1,
            "exports": -1,
            "wildcards": True,
            "conn": -1,
            "leaf": -1,
            "mem_storage": 16 * 1024 * 1024,
            "disk_storage": 16 * 1024 * 1024,
            "streams": 10,
            "consumer": 10,
        },
    )
    user_jwt = make_jwt(account, user, "user", subs=-1, data=-1, payload=-1)

    # Both modes use the same user key; only the JWT server requires its JWT.
    auths = {
        "credentials.env": (
            GENERATED_HEADER
            + f"export NATS_AUTH_NKEY='{user.seed.decode()}'\n"
            + f"export NATS_AUTH_WRONG_NKEY='{wrong_user.seed.decode()}'\n"
            + f"export NATS_AUTH_JWT='{user_jwt}'\n"
        ),
        "nkey.conf": (
            SERVER_CONFIG
            + "authorization { users: [\n"
            + f"  {{ nkey: {user.public_key.decode()} }}\n"
            + "] }\n"
        ),
        "jwt.conf": (
            SERVER_CONFIG
            + f"operator: {operator_jwt}\n"
            + "resolver: MEMORY\n"
            + "resolver_preload: {\n"
            + f"  {system.public_key.decode()}: {system_jwt}\n"
            + f"  {account.public_key.decode()}: {account_jwt}\n"
            + "}\n"
        ),
    }
    output_dir.mkdir(parents=True, exist_ok=True)
    for name, contents in auths.items():
        (output_dir / name).write_text(contents, encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--output-dir",
        type=Path,
        default=Path(__file__).resolve().parent,
        help="output directory (defaults to the directory containing this script)",
    )
    args = parser.parse_args()
    generate_auth(args.output_dir)


if __name__ == "__main__":
    main()
